    /// <summary>
    /// Bans a member in a chat; requires can_restrict_members administrator right. Members can't be banned in private or secret chats. In supergroups and channels, the user will not be able to return to the group on their own using invite links, etc., unless unbanned first
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> BanChatMemberAsync(long chatId = default, MessageSender memberId = default, int bannedUntilDate = default, bool revokeMessages = default)
    {

           using var activity =  StartCallActivity("BanChatMemberAsync", typeof(BanChatMember).FullName ?? "BanChatMemberAsync");

           try
           {
             return client.BanChatMemberAsync(chatId, memberId, bannedUntilDate, revokeMessages);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
